static ut32 omf_count_symb(ut16 total_size, ut32 ct, const ut8 *buf, int buf_size, int bits) {
	ut32 nb_symb = 0;
	ut32 limit = R_MIN (total_size, (ut32)buf_size);
	if (limit < 2) {
		return 0;
	}
	while (ct < limit - 1) {
		ct += buf[ct] + 1 + (bits == 32 ? 4 : 2);
		if (ct > limit - 1) {
			return nb_symb;
		}
		if (buf[ct] & 0x80) {
			ct += 2;
		} else {
			ct++;
		}
		nb_symb++;
	}
	return nb_symb;
}

